import{_ as a,o as e,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Atalho para o dispositivo","description":"","frontmatter":{"title":"Atalho para o dispositivo","id":"eproc-atalho-dispositivo","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.11.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-atalho-dispositivo"}]]},"headers":[],"relativePath":"funcionalidades/eproc-atalho-dispositivo.md","filePath":"funcionalidades/eproc-atalho-dispositivo.md"}'),i={name:"funcionalidades/eproc-atalho-dispositivo.md"};function t(n,o,p,l,d,c){return e(),s("div",null,o[0]||(o[0]=[r('<h1 id="atalho-para-o-dispositivo" tabindex="-1">Atalho para o dispositivo <a class="header-anchor" href="#atalho-para-o-dispositivo" aria-label="Permalink to &quot;Atalho para o dispositivo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Em decisões e despachos longos, o que importa costuma estar no fim. Este recurso põe no topo do documento o link <strong>Ir para o dispositivo</strong>, que leva direto ao início da parte dispositiva, sem precisar rolar o texto inteiro.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, janela de um documento de decisão ou despacho aberto pela tabela de eventos do processo (siglas como DESP, DEC e DESPADEC). O link fica logo no começo do documento, com o logo do eploc.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Na página do processo, abra uma decisão ou um despacho pela tabela de eventos.</li><li>No topo do documento, clique em <strong>Ir para o dispositivo</strong>. O documento rola até o início do dispositivo, que pisca em amarelo por um instante.</li></ol><p>O eploc procura, nesta ordem:</p><ul><li>uma linha só com <strong>DISPOSITIVO</strong>;</li><li>uma linha só com <strong>DETERMINAÇÕES</strong>;</li><li>um parágrafo que começa por <strong>Ante o exposto</strong>.</li></ul><p>Vale a primeira dessa lista que o documento tiver. Assim, um &quot;Ante o exposto&quot; no meio da fundamentação não ganha de um &quot;DISPOSITIVO&quot; que vem depois. Maiúsculas, acentos e a pontuação do fim (&quot;Ante o exposto:&quot;) não fazem diferença.</p><h3 id="usar-outra-expressao" tabindex="-1">Usar outra expressão <a class="header-anchor" href="#usar-outra-expressao" aria-label="Permalink to &quot;Usar outra expressão&quot;">​</a></h3><p>Se você ou o seu gabinete usam outra expressão para abrir o dispositivo (por exemplo, &quot;Isso posto&quot;):</p><ol><li>Num documento que a tenha, selecione a expressão no começo da linha.</li><li>Clique com o botão direito e escolha <strong>Usar como marcador do dispositivo</strong>.</li></ol><p>A expressão fica salva e o link aparece na hora. Ela vale como começo de parágrafo e é procurada depois das três expressões padrão. Sem nada selecionado, o botão direito abre o menu normal do navegador.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><ul><li><strong>Rolar automaticamente até o dispositivo ao abrir o documento</strong> (desligada por padrão): o documento já abre rolado até o dispositivo. O link continua no topo, para voltar a ele.</li><li><strong>Outras expressões que marcam o dispositivo (separadas por 😉</strong>: as expressões salvas pelo botão direito. Dá para editar ou apagar aqui.</li></ul><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Quando o documento não tem nenhuma das expressões, o link não aparece.</li><li>Se o documento for aberto fora da página do processo, o eploc reconhece a decisão ou o despacho pelo título no começo do texto (&quot;DESPACHO/DECISÃO&quot;).</li><li>A expressão precisa estar no começo da linha ou do parágrafo. Se o documento quebrar a expressão em formatações diferentes (por exemplo, só &quot;Ante&quot; em negrito), ela pode não ser encontrada.</li><li>O link não sai na impressão do documento.</li></ul>',18)]))}const h=a(i,[["render",t]]);export{m as __pageData,h as default};
